@Retention(RetentionPolicy.RUNTIME)
@Documented
@Component  // Meta-annotation: @Service includes @Component
public @interface Service {
    @AliasFor(annotation = Component.class)
    String value() default "";
}

// Spring's actual definition of @RestController (simplified)
@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Documented
@Controller  // Meta-annotated with @Controller (which has @Component)
@ResponseBody  // Adds behavior: auto-serialize return values to JSON
public @interface RestController {
    @AliasFor(annotation = Controller.class)
    String value() default "";
}

// Your code using the composed annotations
@Service  // Implicitly includes @Component
public class OrderService {
    // Spring finds this during component scan because @Service has @Component
}

@RestController  // Has @Controller, which has @Component
public class OrderController {
    // Spring finds this AND applies @ResponseBody behavior automatically
}
